import React, { createContext, useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthUser, AuthRequest, AuthResponse } from '../types/auth';
import * as authService from '../services/authService';

interface AuthContextType {
  user: AuthUser | null;
  token: string | null;
  isAuthenticated: boolean;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string) => Promise<void>;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

interface AuthProviderProps {
  children: React.ReactNode;
}

export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const navigate = useNavigate();

  useEffect(() => {
    const storedToken = localStorage.getItem('token');
    if (storedToken) {
      setToken(storedToken);
      setIsAuthenticated(true);
      // As per instruction: "assume token presence implies authentication and user info can be derived or fetched later"
      // For simplicity, we set a placeholder user if a token is present on initial load.
      // A more robust solution might involve decoding the token or making an API call to fetch user details.
      setUser({ email: 'authenticated@example.com' });
    }
  }, []);

  const login = useCallback(async (email: string, password: string) => {
    try {
      const response: AuthResponse = await authService.login({ email, password });
      localStorage.setItem('token', response.token);
      setToken(response.token);
      setIsAuthenticated(true);
      setUser({ email });
    } catch (error) {
      console.error('Login failed:', error);
      throw error;
    }
  }, []);

  const register = useCallback(async (email: string, password: string) => {
    try {
      const response: AuthResponse = await authService.register({ email, password });
      localStorage.setItem('token', response.token);
      setToken(response.token);
      setIsAuthenticated(true);
      setUser({ email });
    } catch (error) {
      console.error('Registration failed:', error);
      throw error;
    }
  }, []);

  const logout = useCallback(() => {
    localStorage.removeItem('token');
    setToken(null);
    setIsAuthenticated(false);
    setUser(null);
    navigate('/login');
  }, [navigate]);

  const contextValue = {
    user,
    token,
    isAuthenticated,
    login,
    register,
    logout,
  };

  return (
    <AuthContext.Provider value={contextValue}>
      {children}
    </AuthContext.Provider>
  );
};

